package site.kael.conversationcompiler.service.settings;
import org.springframework.stereotype.Service; import site.kael.conversationcompiler.domain.settings.*; import site.kael.conversationcompiler.manager.settings.ModelProviderManager; import java.util.*;
@Service public class ModelProviderService { private final ModelProviderManager manager; public ModelProviderService(ModelProviderManager m){manager=m;} public List<ModelProvider> list(){return manager.list();} public ModelProvider get(String id){return manager.get(id);} public List<String> fetch(FetchModelsRequest r){return manager.fetch(r);} public ModelProvider create(ModelProviderRequest r){return manager.save(null,r);} public ModelProvider update(String id,ModelProviderRequest r){return manager.save(id,r);} public void delete(String id){manager.delete(id);} }
